const lessons=[{"sentences":[{"speaker":"A","text":"Attention valued shoppers because our main entrance is undergoing urgent repairs today.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.456041666666667},{"speaker":"A","text":"All customers must enter through the side doors located near the parking lot.","position":2,"audioStartSeconds":5.656041666666667,"audioEndSeconds":10.502166666666668},{"speaker":"A","text":"Staff members will guide you safely past the construction zone until evening.","position":3,"audioStartSeconds":10.702166666666667,"audioEndSeconds":15.702166666666667},{"speaker":"A","text":"We apologize for any temporary inconvenience while we improve our store.","position":4,"audioStartSeconds":15.902166666666666,"audioEndSeconds":20.708875},{"speaker":"A","text":"Please speak with an employee at the front desk if you need assistance.","position":5,"audioStartSeconds":20.908875,"audioEndSeconds":25.23875},{"speaker":"A","text":"Thank you for your patience while we complete these necessary facility updates.","position":6,"audioStartSeconds":25.43875,"audioEndSeconds":30.322791666666667},{"speaker":"A","text":"Normal opening hours will resume tomorrow morning once the builders finish.","position":7,"audioStartSeconds":30.522791666666667,"audioEndSeconds":35.26504166666667},{"speaker":"A","role":"section-start","text":"We are thrilled to announce our grand reopening celebration this coming weekend.","position":8,"audioStartSeconds":40.26504166666667,"audioEndSeconds":45.17483333333333},{"speaker":"A","text":"The first fifty visitors on Saturday will receive a complimentary gift bag.","position":9,"audioStartSeconds":45.374833333333335,"audioEndSeconds":50.361958333333334},{"speaker":"A","text":"Our management team organized special discounts across all departments for everyone.","position":10,"audioStartSeconds":50.56195833333334,"audioEndSeconds":55.897},{"speaker":"A","text":"Live musical performances will take place in the central courtyard during afternoon hours.","position":11,"audioStartSeconds":56.097,"audioEndSeconds":61.792875},{"speaker":"A","text":"Visitors should register online beforehand if they wish to join cooking workshops.","position":12,"audioStartSeconds":61.992875,"audioEndSeconds":67.21195833333333},{"speaker":"A","text":"Free parking is available behind the main building throughout the entire weekend.","position":13,"audioStartSeconds":67.41195833333333,"audioEndSeconds":72.476375},{"speaker":"A","text":"We look forward to celebrating this exciting milestone with our community.","position":14,"audioStartSeconds":72.676375,"audioEndSeconds":77.42}],"questions":[{"prompt":"What is the main reason for the first announcement?","options":["To report a store robbery.","To explain entrance changes.","To announce weekend sales."],"answer":"B","evidenceSentence":1,"evidence":"Attention valued shoppers because our main entrance is undergoing urgent repairs today.","explanation":"Thông báo đầu tiên nhằm thông báo về việc thay đổi lối ra vào do sửa chữa."},{"prompt":"Where should customers enter the building today?","options":["Through the side doors.","Through the loading dock.","Through the roof terrace."],"answer":"A","evidenceSentence":2,"evidence":"All customers must enter through the side doors located near the parking lot.","explanation":"Khách hàng phải đi vào qua các cửa bên hông gần bãi đỗ xe."},{"prompt":"When will normal operating hours return?","options":["Next month.","Tomorrow morning.","Next weekend."],"answer":"B","evidenceSentence":7,"evidence":"Normal opening hours will resume tomorrow morning once the builders finish.","explanation":"Giờ mở cửa bình thường sẽ trở lại vào sáng ngày mai."},{"prompt":"What event is announced in the second talk?","options":["A staff training seminar.","A grand reopening celebration.","An annual charity auction."],"answer":"B","evidenceSentence":8,"evidence":"We are thrilled to announce our grand reopening celebration this coming weekend.","explanation":"Bài nói thứ hai thông báo về lễ kỷ niệm mở cửa lại quy mô lớn."},{"prompt":"What will the first fifty visitors receive on Saturday?","options":["A complimentary gift bag.","A discounted lunch voucher.","A free parking pass."],"answer":"A","evidenceSentence":9,"evidence":"The first fifty visitors on Saturday will receive a complimentary gift bag.","explanation":"Năm mươi vị khách đầu tiên vào thứ Bảy sẽ nhận được một túi quà miễn phí."},{"prompt":"What must visitors do to join the cooking workshops?","options":["Buy a special ticket.","Register online beforehand.","Arrive two hours early."],"answer":"B","evidenceSentence":12,"evidence":"Visitors should register online beforehand if they wish to join cooking workshops.","explanation":"Khách tham quan cần đăng ký trực tuyến trước nếu muốn tham gia các buổi hội thảo nấu ăn."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
